// LoadEmf allows an eager lookup of values, cached into the
// loaded structs of the objects. This is for an N-1 relationship.
func (produtoL) LoadEmf(ctx context.Context, e boil.ContextExecutor, singular bool, maybeProduto interface{}, mods queries.Applicator) error {
	var slice []*Produto
	var object *Produto

	if singular {
		var ok bool
		object, ok = maybeProduto.(*Produto)
		if !ok {
			object = new(Produto)
			ok = queries.SetFromEmbeddedStruct(&object, &maybeProduto)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", object, maybeProduto))
			}
		}
	} else {
		s, ok := maybeProduto.(*[]*Produto)
		if ok {
			slice = *s
		} else {
			ok = queries.SetFromEmbeddedStruct(&slice, maybeProduto)
			if !ok {
				return errors.New(fmt.Sprintf("failed to set %T from embedded struct %T", slice, maybeProduto))
			}
		}
	}

	args := make(map[interface{}]struct{})
	if singular {
		if object.R == nil {
			object.R = &produtoR{}
		}
		args[object.EmfID] = struct{}{}

	} else {
		for _, obj := range slice {
			if obj.R == nil {
				obj.R = &produtoR{}
			}

			args[obj.EmfID] = struct{}{}

		}
	}

	if len(args) == 0 {
		return nil
	}

	argsSlice := make([]interface{}, len(args))
	i := 0
	for arg := range args {
		argsSlice[i] = arg
		i++
	}

	query := NewQuery(
		qm.From(`empresa_filial`),
		qm.WhereIn(`empresa_filial.emf_id in ?`, argsSlice...),
	)
	if mods != nil {
		mods.Apply(query)
	}

	results, err := query.QueryContext(ctx, e)
	if err != nil {
		return errors.Wrap(err, "failed to eager load EmpresaFilial")
	}

	var resultSlice []*EmpresaFilial
	if err = queries.Bind(results, &resultSlice); err != nil {
		return errors.Wrap(err, "failed to bind eager loaded slice EmpresaFilial")
	}

	if err = results.Close(); err != nil {
		return errors.Wrap(err, "failed to close results of eager load for empresa_filial")
	}
	if err = results.Err(); err != nil {
		return errors.Wrap(err, "error occurred during iteration of eager loaded relations for empresa_filial")
	}

	if len(empresaFilialAfterSelectHooks) != 0 {
		for _, obj := range resultSlice {
			if err := obj.doAfterSelectHooks(ctx, e); err != nil {
				return err
			}
		}
	}

	if len(resultSlice) == 0 {
		return nil
	}

	if singular {
		foreign := resultSlice[0]
		object.R.Emf = foreign
		if foreign.R == nil {
			foreign.R = &empresaFilialR{}
		}
		foreign.R.EmfProdutos = append(foreign.R.EmfProdutos, object)
		return nil
	}

	for _, local := range slice {
		for _, foreign := range resultSlice {
			if local.EmfID == foreign.EmfID {
				local.R.Emf = foreign
				if foreign.R == nil {
					foreign.R = &empresaFilialR{}
				}
				foreign.R.EmfProdutos = append(foreign.R.EmfProdutos, local)
				break
			}
		}
	}

	return nil
}

