// SetProAgendaItems removes all previously related items of the
// produto replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Pro's ProAgendaItems accordingly.
// Replaces o.R.ProAgendaItems with related.
// Sets related.R.Pro's ProAgendaItems accordingly.
func (o *Produto) SetProAgendaItems(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*AgendaItem) error {
	query := "update `agenda_item` set `pro_id` = null where `pro_id` = ?"
	values := []interface{}{o.ProID}
	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, query)
		fmt.Fprintln(writer, values)
	}
	_, err := exec.ExecContext(ctx, query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.ProAgendaItems {
			queries.SetScanner(&rel.ProID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Pro = nil
		}
		o.R.ProAgendaItems = nil
	}

	return o.AddProAgendaItems(ctx, exec, insert, related...)
}

// RemoveProAgendaItems relationships from objects passed in.
// Removes related items from R.ProAgendaItems (uses pointer comparison, removal does not keep order)
// Sets related.R.Pro.
func (o *Produto) RemoveProAgendaItems(ctx context.Context, exec boil.ContextExecutor, related ...*AgendaItem) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.ProID, nil)
		if rel.R != nil {
			rel.R.Pro = nil
		}
		if _, err = rel.Update(ctx, exec, boil.Whitelist("pro_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.ProAgendaItems {
			if rel != ri {
				continue
			}

			ln := len(o.R.ProAgendaItems)
			if ln > 1 && i < ln-1 {
				o.R.ProAgendaItems[i] = o.R.ProAgendaItems[ln-1]
			}
			o.R.ProAgendaItems = o.R.ProAgendaItems[:ln-1]
			break
		}
	}

	return nil
}

