// FindProduto retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindProduto(ctx context.Context, exec boil.ContextExecutor, proID int, selectCols ...string) (*Produto, error) {
	produtoObj := &Produto{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from `produto` where `pro_id`=?", sel,
	)

	q := queries.Raw(query, proID)

	err := q.Bind(ctx, exec, produtoObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "models: unable to select from produto")
	}

	if err = produtoObj.doAfterSelectHooks(ctx, exec); err != nil {
		return produtoObj, err
	}

	return produtoObj, nil
}

